import json,subprocess
a=json.load(open('.local-delivery/audit-all-20261116/git-independent-audit.json'))
def g(*x):return subprocess.check_output(['git',*x])
cache={}
def t(s):
 if s not in cache:cache[s]={x.split(b'\t',1)[1].decode():x.split(b'\t',1)[0] for x in g('ls-tree','-rz',s).split(b'\0') if x}
 return cache[s]
for r in a['pr_inventory']:
 assert [x.decode() for x in g('diff','--name-only','-z',r['scope_base'],r['head_sha']).split(b'\0') if x]==r['changed_paths']
 for s,c in r['comparisons'].items():
  assert [f for f in r['changed_paths'] if t(r['head_sha']).get(f)==t(s).get(f)]==c['exact_paths']
  assert [f for f in r['changed_paths'] if f in t(r['head_sha']) and f not in t(s)]==c['missing_contributed_paths']
u=[{p:v for p,v in t(s).items() if p.startswith('docs/ux/')} for s in [a['pb2_ux'],a['main'],a['candidate'],a['pr412']]];assert len(u[0])==117 and all(x==u[0] for x in u)
assert sorted(set(t(a['candidate']))-set(t(a['pr412'])))==a['pr412_vs_candidate']['missing_candidate_paths']
print(json.dumps({'prs':len(a['pr_inventory']),'branches':len(a['branches']),'ux_exact':117,'missing_candidate_paths_in_pr412':len(a['pr412_vs_candidate']['missing_candidate_paths'])},sort_keys=True))
